curl -s -X POST https://slack.com/api/conversations.history -d "token=<TOKEN>" -d "channel=C-DESIGNSYNC" -d "limit=200" | python3 -c "
import json,sys
data=json.load(sys.stdin)
toms={'U_TOMA','U_TOMD','U_TOMR'}
for msg in data.get('messages',[]):
    reactions = msg.get('reactions',[])
    for r in reactions:
        users = r.get('users',[])
        for u in users:
            if u in toms:
                print('MATCH', msg.get('ts'), r.get('name'), u)
"

